package com.blog.entity;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="users", uniqueConstraints={@UniqueConstraint(columnNames="email"),@UniqueConstraint(columnNames="username")}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=50) private String username; @Column(nullable=false,length=120) private String email; @Column(nullable=false) private String password; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Role role; private String firstName; private String lastName; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @OneToMany(mappedBy="author") private List<Post> posts=new ArrayList<>(); @OneToMany(mappedBy="user") private List<Comment> comments=new ArrayList<>(); @PrePersist void created(){createdAt=updatedAt=Instant.now();} @PreUpdate void updated(){updatedAt=Instant.now();} }
